package repository

import (
    "context"
    "errors"
    "fmt"
    "github.com/jackc/pgx/v5"
)

type Row interface { Scan(...any) error }
type DB interface { QueryRow(context.Context, string, ...any) pgx.Row }
type Repository struct { db DB }
type Order struct { ID, Status string }
var ErrNotFound = errors.New("order not found")

func (r Repository) GetOrder(ctx context.Context, id string) (Order, error) {
    const query = `SELECT id, status FROM orders WHERE id = $1`
    var out Order
    err := r.db.QueryRow(ctx, query, id).Scan(&out.ID, &out.Status)
    if errors.Is(err, pgx.ErrNoRows) { return Order{}, ErrNotFound }
    if err != nil { return Order{}, fmt.Errorf("get order %q: %w", id, err) }
    return out, nil
}

